contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 excess) public {
        // deposit nothing; caller (this contract) has staked 0 tokens
        uint256 balBefore = c.balanceOf(address(this));
        uint256 supplyBefore = c.totalSupply();

        require(c.balanceOf(address(this)) == 0);

        // any amount strictly greater than the staked balance must revert
        uint256 amount = balBefore + (excess % 1000) + 1;
        bool reverted;
        try c.withdraw(amount, false) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 balAfter = c.balanceOf(address(this));
        uint256 supplyAfter = c.totalSupply();

        assert(
            reverted &&
            balAfter == balBefore &&
            supplyAfter == supplyBefore
        );
    }
}

